window.QUESTION_BANK = [{"module": 1, "number": 1, "question": "<p>Which best describes Machine Learning according to the engineering-oriented definition?</p>", "options": [["A", "A computer follows manually programmed rules perfectly"], ["B", "Performance on a task improves through experience"], ["C", "A computer automatically becomes intelligent over time"], ["D", "A computer stores increasing amounts of data"]], "answers": ["B"], "multiple": false, "explanation": "<p>Mitchell's definition: performance $P$ on task $T$ improves through experience $E$.</p>"}, {"module": 1, "number": 2, "question": "<p>A house-price model has:</p>\n<ul>\n<li>historical house records</li>\n<li>task of predicting selling price</li>\n<li>mean prediction error</li>\n</ul>\n<p>What represents <strong>E</strong>?</p>", "options": [["A", "Predicting selling price"], ["B", "Historical house records"], ["C", "Mean prediction error"], ["D", "The prediction algorithm"]], "answers": ["B"], "multiple": false, "explanation": "<p>Experience = historical data.</p>"}, {"module": 1, "number": 3, "question": "<p>A bank wants to predict whether a transaction is <code>\"Fraud\"</code> or <code>\"Legitimate\"</code>.</p>\n<p>This is:</p>", "options": [["A", "Regression"], ["B", "Clustering"], ["C", "Classification"], ["D", "Reinforcement learning"]], "answers": ["C"], "multiple": false, "explanation": "<p>Fraud/Legitimate are categories.</p>"}, {"module": 1, "number": 4, "question": "<p>A property company predicts the selling price of a condominium in RM.</p>\n<p>This is:</p>", "options": [["A", "Classification"], ["B", "Regression"], ["C", "Clustering"], ["D", "Anomaly detection"]], "answers": ["B"], "multiple": false, "explanation": "<p>RM price is numerical.</p>"}, {"module": 1, "number": 5, "question": "<p>A retailer has customer transaction data but no predefined customer groups. An algorithm discovers four groups based on spending behaviour.</p>\n<p>This is:</p>", "options": [["A", "Classification"], ["B", "Regression"], ["C", "Clustering"], ["D", "Reinforcement learning"]], "answers": ["C"], "multiple": false, "explanation": "<p>No predefined labels; groups are discovered.</p>"}, {"module": 1, "number": 6, "question": "<p>Which problem is most clearly anomaly detection?</p>", "options": [["A", "Predict tomorrow's temperature"], ["B", "Identify suspicious transactions that differ from normal behaviour"], ["C", "Divide customers into spending groups"], ["D", "Predict whether a student will pass"]], "answers": ["B"], "multiple": false, "explanation": "<p>Anomalies are unusual patterns/events.</p>"}, {"module": 1, "number": 7, "question": "<p>Which is required for supervised learning?</p>", "options": [["A", "No historical data"], ["B", "Labels/known target outcomes"], ["C", "Rewards from an environment"], ["D", "Clusters must already exist"]], "answers": ["B"], "multiple": false, "explanation": "<p>Supervised learning uses labelled data.</p>"}, {"module": 1, "number": 8, "question": "<p>An AI plays a game, receives +10 when it wins and −10 when it loses, and adjusts its behaviour.</p>\n<p>This is:</p>", "options": [["A", "Supervised learning"], ["B", "Unsupervised learning"], ["C", "Reinforcement learning"], ["D", "Batch learning"]], "answers": ["C"], "multiple": false, "explanation": "<p>Learning through reward/punishment.</p>"}, {"module": 1, "number": 9, "question": "<p>Which statement about unsupervised learning is most accurate according to the lecture?</p>", "options": [["A", "It always predicts numerical values"], ["B", "It learns from labelled examples"], ["C", "It finds patterns or similarities in unlabelled data"], ["D", "It requires reward signals"]], "answers": ["C"], "multiple": false, "explanation": "<p>Unsupervised learning looks for structure in unlabelled data.</p>"}, {"module": 1, "number": 10, "question": "<p>A credit model is retrained every month using all newly collected data. Between retrainings, the model does not update itself.</p>\n<p>This is:</p>", "options": [["A", "Online learning"], ["B", "Batch learning"], ["C", "Reinforcement learning"], ["D", "Instance-based learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>Retrain periodically rather than incrementally.</p>"}, {"module": 1, "number": 11, "question": "<p>A model updates itself after receiving each new transaction.</p>\n<p>This is:</p>", "options": [["A", "Batch learning"], ["B", "Online learning"], ["C", "Model evaluation"], ["D", "KDD"]], "answers": ["B"], "multiple": false, "explanation": "<p>Model updates incrementally.</p>"}, {"module": 1, "number": 12, "question": "<p>A dataset is too large to fit into RAM. The algorithm loads part of the dataset, trains, then loads another part.</p>\n<p>This is:</p>", "options": [["A", "Clustering"], ["B", "Out-of-core learning"], ["C", "Underfitting"], ["D", "Instance-based learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>That's the lecture's definition of out-of-core learning.</p>"}, {"module": 1, "number": 13, "question": "<p>A new customer is classified based largely on the five most similar previous customers.</p>\n<p>This is:</p>", "options": [["A", "Model-based learning"], ["B", "Instance-based learning"], ["C", "Reinforcement learning"], ["D", "Batch learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>Prediction relies on similar stored instances.</p>"}, {"module": 1, "number": 14, "question": "<p>A model learns:</p>\n<div class=\"math-display\">$$\\text{Price} = 300(\\text{Size})+50000$$</div>\n<p>and uses this relationship for new houses.</p>\n<p>This is:</p>", "options": [["A", "Instance-based learning"], ["B", "Model-based learning"], ["C", "Unsupervised learning"], ["D", "Reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>A general relationship/model has been learned.</p>"}, {"module": 1, "number": 15, "question": "<p>Which result most strongly suggests <strong>overfitting</strong>?</p>", "options": [["A", "Training accuracy 60%, test accuracy 61%"], ["B", "Training accuracy 98%, test accuracy 65%"], ["C", "Training accuracy 90%, test accuracy 89%"], ["D", "Training accuracy 55%, test accuracy 50%"]], "answers": ["B"], "multiple": false, "explanation": "<p>Huge training-test gap.</p>"}, {"module": 1, "number": 16, "question": "<p>Which result most strongly suggests <strong>underfitting</strong>?</p>", "options": [["A", "Training accuracy 99%, test accuracy 60%"], ["B", "Training accuracy 94%, test accuracy 92%"], ["C", "Training accuracy 58%, test accuracy 56%"], ["D", "Training accuracy 100%, test accuracy 99%"]], "answers": ["C"], "multiple": false, "explanation": "<p>Poor even on training data indicates insufficient learning.</p>"}, {"module": 1, "number": 17, "question": "<p>Which is a possible solution to overfitting according to the lecture?</p>", "options": [["A", "Make the model more complicated"], ["B", "Add more irrelevant features"], ["C", "Gather more training data"], ["D", "Increase noise in the data"]], "answers": ["C"], "multiple": false, "explanation": "<p>More training data is one lecture-listed remedy.</p>"}, {"module": 1, "number": 18, "question": "<p>Which can help fix underfitting?</p>", "options": [["A", "Select a more powerful model"], ["B", "Reduce the amount of useful data"], ["C", "Add more constraints to the model"], ["D", "Remove useful features"]], "answers": ["A"], "multiple": false, "explanation": "<p>Underfitting can require a more powerful model.</p>"}, {"module": 1, "number": 19, "question": "<p>Why must training data be representative?</p>", "options": [["A", "It guarantees zero error"], ["B", "The model must generalize to future observations similar to the target population"], ["C", "It allows all algorithms to become supervised"], ["D", "It removes the need for testing"]], "answers": ["B"], "multiple": false, "explanation": "<p>Training data should represent the cases you want to generalize to.</p>"}, {"module": 1, "number": 20, "question": "<p>A dataset contains:</p>\n<pre><code class=\"language-text\">Age = 220\nHeight = 8.7 metres\nIncome = missing\n</code></pre>\n<p>The major problem is:</p>", "options": [["A", "Reinforcement learning"], ["B", "Poor-quality/noisy data"], ["C", "Online learning"], ["D", "Underfitting"]], "answers": ["B"], "multiple": false, "explanation": "<p>Errors, missing data, outliers, noise.</p>"}, {"module": 1, "number": 21, "question": "<p>Creating:</p>\n<div class=\"math-display\">$$\\text{DebtToIncome}=\\frac{\\text{Debt}}{\\text{Income}}$$</div>\n<p>from existing variables is an example of:</p>", "options": [["A", "Deployment"], ["B", "Feature engineering"], ["C", "Reinforcement learning"], ["D", "Clustering"]], "answers": ["B"], "multiple": false, "explanation": "<p>Creating a more useful feature.</p>"}, {"module": 1, "number": 22, "question": "<p>Which CRISP-DM phase comes first?</p>", "options": [["A", "Modeling"], ["B", "Evaluation"], ["C", "Business Understanding"], ["D", "Data Preparation"]], "answers": ["C"], "multiple": false, "explanation": "<p>CRISP-DM begins with Business Understanding.</p>"}, {"module": 1, "number": 23, "question": "<p>Which framework explicitly begins with <strong>Business Understanding</strong> and includes <strong>Deployment</strong>?</p>", "options": [["A", "KDD"], ["B", "SEMMA"], ["C", "CRISP-DM"], ["D", "K-Means"]], "answers": ["C"], "multiple": false, "explanation": "<p>That's the major distinguishing feature of CRISP-DM here.</p>"}, {"module": 1, "number": 24, "question": "<p>Which correctly represents SEMMA?</p>", "options": [["A", "Sample → Explore → Modify → Model → Assess"], ["B", "Select → Evaluate → Modify → Mine → Analyze"], ["C", "Study → Explore → Model → Measure → Apply"], ["D", "Sample → Evaluate → Mine → Modify → Analyze"]], "answers": ["A"], "multiple": false, "explanation": "<p>SEMMA = Sample, Explore, Modify, Model, Assess.</p>"}, {"module": 1, "number": 25, "question": "<p>Which is the correct broad idea behind KDD?</p>", "options": [["A", "Reward → action → reinforcement"], ["B", "Data → selection/preprocessing/transformation/mining/evaluation → knowledge"], ["C", "Data → neural network only"], ["D", "Business objective → reinforcement → deployment"]], "answers": ["B"], "multiple": false, "explanation": "<p>KDD structures the journey from raw data to knowledge.</p>"}, {"module": 1, "number": 26, "question": "<p>A spam classifier is trained once using one million labelled emails. It then immediately classifies every incoming email but never updates its parameters until next month's retraining.</p>\n<p>Which description is most accurate?</p>", "options": [["A", "Online supervised learning"], ["B", "Batch supervised learning"], ["C", "Online unsupervised learning"], ["D", "Reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>This is a good trap.</p>\n<p>It makes <strong>real-time predictions</strong>, but it does <strong>not learn online</strong>.</p>"}, {"module": 1, "number": 27, "question": "<p>A company gives an algorithm customer data with no customer segment labels. The algorithm discovers three clusters. Managers then name the groups <code>\"Budget\"</code>, <code>\"Regular\"</code>, and <code>\"Premium\"</code>.</p>\n<p>What learning happened?</p>", "options": [["A", "Supervised classification"], ["B", "Unsupervised clustering"], ["C", "Regression"], ["D", "Reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>The humans naming clusters afterward does not magically make the original learning supervised.</p>"}, {"module": 1, "number": 28, "question": "<p>A model obtains:</p>\n<pre><code class=\"language-text\">Training error = 40%\nTest error = 42%\n</code></pre>\n<p>Which interpretation is strongest?</p>", "options": [["A", "Severe overfitting"], ["B", "Likely underfitting"], ["C", "Excellent generalization"], ["D", "Data leakage"]], "answers": ["B"], "multiple": false, "explanation": "<p>The training performance itself is poor.</p>\n<p>The model isn't even learning the known data adequately.</p>"}, {"module": 1, "number": 29, "question": "<p>A model obtains:</p>\n<pre><code class=\"language-text\">Training error = 1%\nTest error = 24%\n</code></pre>\n<p>Which interpretation is strongest?</p>", "options": [["A", "Underfitting"], ["B", "Overfitting"], ["C", "Clustering"], ["D", "Out-of-core learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>Low training error + much higher test error = classic overfitting.</p>"}, {"module": 1, "number": 30, "question": "<p>A hospital collects 2 million patient records, but every patient comes from the same specialist cardiac clinic. The model is deployed to predict outcomes for the entire population.</p>\n<p>What is the most obvious concern?</p>", "options": [["A", "Dataset is too small"], ["B", "Training data may be nonrepresentative"], ["C", "Online learning is impossible"], ["D", "Model must use reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>More data is not automatically better if the population is biased.</p>\n<p>The lecture emphasizes that training data should represent the new cases the model is expected to generalize to.</p>"}, {"module": 1, "number": 31, "question": "<p>A team begins by asking:</p>\n<blockquote>\n<p>What business objective are we trying to achieve?</p>\n</blockquote>\n<p>Which framework most explicitly emphasizes this as its first phase?</p>", "options": [["A", "SEMMA"], ["B", "KDD"], ["C", "CRISP-DM"], ["D", "Online learning"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 1, "number": 32, "question": "<p>Which stage belongs to SEMMA but not as a named CRISP-DM phase?</p>", "options": [["A", "Sample"], ["B", "Modeling"], ["C", "Evaluation"], ["D", "Data Preparation"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 1, "number": 33, "question": "<p>Which one ends with an explicit <strong>Deployment</strong> phase in the lecture?</p>", "options": [["A", "KDD"], ["B", "SEMMA"], ["C", "CRISP-DM"], ["D", "All three"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 1, "question": "<p>A company says:</p>\n<blockquote>\n<p>“We want to reduce unexpected equipment downtime.”</p>\n</blockquote>\n<p>Which CRISP-DM phase handles this first?</p>", "options": [["A", "Modeling"], ["B", "Business Understanding"], ["C", "Data Preparation"], ["D", "Deployment"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 2, "question": "<p>The business goal is converted into:</p>\n<blockquote>\n<p>“Predict equipment failure within the next 24 hours.”</p>\n</blockquote>\n<p>This is primarily part of:</p>", "options": [["A", "Business Understanding"], ["B", "Data Cleaning"], ["C", "Feature Scaling"], ["D", "Deployment"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 3, "question": "<p>A data scientist investigates available sensor logs, missing values and whether the data is relevant.</p>\n<p>Which phase?</p>", "options": [["A", "Modeling"], ["B", "Deployment"], ["C", "Data Understanding"], ["D", "Evaluation"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 4, "question": "<p>Encoding categories, handling missing values and scaling numeric features belongs mainly to:</p>", "options": [["A", "Data Preparation"], ["B", "Business Understanding"], ["C", "Deployment"], ["D", "Evaluation"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 5, "question": "<p>Which phase asks:</p>\n<blockquote>\n<p>“Does the model satisfy the business criteria defined earlier?”</p>\n</blockquote>", "options": [["A", "Modeling"], ["B", "Evaluation"], ["C", "Data Understanding"], ["D", "Data Retrieval"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 6, "question": "<p>Which statement is most accurate?</p>", "options": [["A", "CRISP-DM and ML Pipeline are exactly the same"], ["B", "CRISP-DM is mainly code"], ["C", "ML Pipeline is more technically focused"], ["D", "CRISP-DM begins with feature scaling"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 7, "question": "<p>Which sequence is correct?</p>", "options": [["A", "Modeling → Business Understanding → Deployment"], ["B", "Business Understanding → Data Understanding → Data Preparation"], ["C", "Deployment → Modeling → Evaluation"], ["D", "Data Preparation → Business Understanding → Modeling"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 8, "question": "<p>Which is typically one of the heaviest stages according to the lecture?</p>", "options": [["A", "Data Preparation"], ["B", "Deployment"], ["C", "Business Understanding"], ["D", "Evaluation"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 9, "question": "<p>Which format is naturally tabular and generally convenient for pandas?</p>", "options": [["A", "JSON"], ["B", "CSV"], ["C", "XML"], ["D", "HTML"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 10, "question": "<p>Which format commonly contains nested key-value pairs?</p>", "options": [["A", "CSV"], ["B", "SQL"], ["C", "JSON"], ["D", "TXT"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 11, "question": "<p>Which format is tag-based and commonly associated with legacy enterprise systems?</p>", "options": [["A", "XML"], ["B", "CSV"], ["C", "JSON"], ["D", "SQL"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 12, "question": "<p>Which is most closely associated with relational tables and enterprise databases?</p>", "options": [["A", "HTML"], ["B", "SQL"], ["C", "JSON"], ["D", "CSV"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 13, "question": "<p>Why may JSON require additional preprocessing before classical ML?</p>", "options": [["A", "It is always encrypted"], ["B", "It is hierarchical and may need flattening"], ["C", "It cannot contain numbers"], ["D", "It contains only images"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 14, "question": "<p>Web scraping broadly involves:</p>\n<div class=\"math-display\">$$\\text{Crawl} \\rightarrow \\text{Scrape}$$</div>\n<p><strong>Crawl:</strong> obtain webpages.</p>\n<p><strong>Scrape:</strong> extract desired information.</p>\n<p>Which step retrieves webpages from URLs?</p>", "options": [["A", "Scraping"], ["B", "Crawling"], ["C", "Scaling"], ["D", "Encoding"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 15, "question": "<p>Which step extracts specific information from retrieved HTML?</p>", "options": [["A", "Scraping"], ["B", "Crawling"], ["C", "Modeling"], ["D", "Binning"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 16, "question": "<p>Which feature is categorical?</p>", "options": [["A", "Age = 21"], ["B", "Price = 99.90"], ["C", "Colour = Red"], ["D", "Height = 181"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 17, "question": "<p>Which is the most likely preprocessing for:</p>\n<pre><code class=\"language-text\">Colour = Red / Blue / Green\n</code></pre>", "options": [["A", "Scaling"], ["B", "Categorical encoding"], ["C", "Tokenization"], ["D", "Date extraction"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 18, "question": "<p>Which is most appropriate for a datetime feature?</p>", "options": [["A", "Extract month/day/hour"], ["B", "Always one-hot encode every individual timestamp"], ["C", "Remove it automatically"], ["D", "Apply TF-IDF"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 19, "question": "<p>Which preprocessing is most closely associated with natural-language text?</p>", "options": [["A", "Tokenization"], ["B", "Min-Max scaling only"], ["C", "SQL join"], ["D", "Forward fill only"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 20, "question": "<p>Which function is best for seeing column data types?</p>", "options": [["A", "<code>df.describe()</code>"], ["B", "<code>df.info()</code>"], ["C", "<code>df.groupby()</code>"], ["D", "<code>df.dropna()</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 21, "question": "<p>Which function gives mean, standard deviation, min and max?</p>", "options": [["A", "<code>df.info()</code>"], ["B", "<code>df.describe()</code>"], ["C", "<code>df.ffill()</code>"], ["D", "<code>df.rename()</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 22, "question": "<p>Suppose a column contains 1000 rows but <code>df.info()</code> reports 940 non-null values.</p>\n<p>How many values are missing?</p>", "options": [["A", "40"], ["B", "60"], ["C", "940"], ["D", "1000"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 23, "question": "<p>The lecture presents three broad strategies:</p>\n<div class=\"math-display\">$$\\text{Remove}$$</div>\n<div class=\"math-display\">$$\\text{Impute}$$</div>\n<div class=\"math-display\">$$\\text{Forward/Backward fill}$$</div>\n<p>What does this do?</p>\n<pre><code class=\"language-python\">df.dropna()\n</code></pre>", "options": [["A", "Replaces missing values"], ["B", "Removes observations containing missing values"], ["C", "Finds duplicate records"], ["D", "Converts values to numeric"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 24, "question": "<p>What does this do?</p>\n<pre><code class=\"language-python\">df[&quot;price&quot;].fillna(df[&quot;price&quot;].mean())\n</code></pre>", "options": [["A", "Removes price"], ["B", "Replaces missing prices with mean price"], ["C", "Calculates median"], ["D", "Removes duplicates"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 25, "question": "<p>When is median often preferable to mean for numerical imputation?</p>", "options": [["A", "Strong outliers exist"], ["B", "No missing values exist"], ["C", "The feature is text"], ["D", "The data contains only categories"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 26, "question": "<p>For the values:</p>\n<pre><code class=\"language-text\">100\n110\n120\n1000\nNaN\n</code></pre>\n<p>which central tendency is less affected by <code>1000</code>?</p>", "options": [["A", "Mean"], ["B", "Median"], ["C", "Variance"], ["D", "Range"]], "answers": ["B"], "multiple": false, "explanation": "<p>Because the extreme value pulls the mean upward.</p>"}, {"module": 2, "number": 27, "question": "<p>Which missing-value strategy is particularly reasonable for ordered/time-series data when the previous state tends to persist?</p>", "options": [["A", "One-hot encoding"], ["B", "Forward fill"], ["C", "TF-IDF"], ["D", "Standardization"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 28, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df.ffill()\n</code></pre>\n<p>do?</p>", "options": [["A", "Copies the next known value backward"], ["B", "Copies the previous known value forward"], ["C", "Deletes all missing rows"], ["D", "Converts values to float"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 29, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df.bfill()\n</code></pre>\n<p>do?</p>", "options": [["A", "Uses the following observation to fill a missing value"], ["B", "Uses the previous observation"], ["C", "Binarizes the column"], ["D", "Removes outliers"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 30, "question": "<p>Which command counts duplicated rows?</p>\n<pre><code class=\"language-python\">?\n</code></pre>", "options": [["A", "<code>df.isna().sum()</code>"], ["B", "<code>df.duplicated().sum()</code>"], ["C", "<code>df.describe()</code>"], ["D", "<code>df.groupby()</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 31, "question": "<p>Which removes exact duplicates?</p>", "options": [["A", "<code>df.drop_duplicates()</code>"], ["B", "<code>df.dropna()</code>"], ["C", "<code>df.ffill()</code>"], ["D", "<code>df.to_numeric()</code>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 32, "question": "<p>Why should duplicates not always be automatically removed?</p>", "options": [["A", "Pandas cannot remove them"], ["B", "Some apparently identical records may represent genuine repeated events"], ["C", "Duplicate rows are required for regression"], ["D", "Duplicates improve model accuracy"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 33, "question": "<p>A column contains:</p>\n<pre><code class=\"language-text\">&quot;2026-10-03&quot;\n</code></pre>\n<p>but pandas stores it as <code>object</code>.</p>\n<p>Which function is appropriate?</p>", "options": [["A", "<code>pd.to_datetime()</code>"], ["B", "<code>pd.get_dummies()</code>"], ["C", "<code>df.groupby()</code>"], ["D", "<code>df.drop_duplicates()</code>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 34, "question": "<p>A column contains:</p>\n<pre><code class=\"language-text\">&quot;150.00&quot;\n</code></pre>\n<p>as text but should be numeric.</p>\n<p>Which function is appropriate?</p>", "options": [["A", "<code>pd.to_numeric()</code>"], ["B", "<code>pd.to_datetime()</code>"], ["C", "<code>pd.qcut()</code>"], ["D", "<code>pd.concat()</code>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 35, "question": "<p>Know the conceptual distinction:</p>\n<div class=\"math-display\">$$\\text{Column Selection}\n=\n\\text{Which variables}?$$</div>\n<div class=\"math-display\">$$\\text{Row Filtering}\n=\n\\text{Which observations}?$$</div>\n<p>What does:</p>\n<pre><code class=\"language-python\">df[&quot;price&quot;]\n</code></pre>\n<p>do?</p>", "options": [["A", "Selects the <code>price</code> column"], ["B", "Selects the first row"], ["C", "Removes the price column"], ["D", "Calculates average price"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 36, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df[df[&quot;price&quot;] &gt; 100]\n</code></pre>\n<p>do?</p>", "options": [["A", "Keeps rows where price exceeds 100"], ["B", "Replaces prices below 100"], ["C", "Sorts by price"], ["D", "Selects only the column name"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 37, "question": "<p>What does <code>iloc</code> mainly select by?</p>", "options": [["A", "Column labels only"], ["B", "Integer position"], ["C", "Data type"], ["D", "Missing-value count"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 38, "question": "<p>Which is feature engineering?</p>", "options": [["A", "Delete the whole dataset"], ["B", "Extract <code>month</code> from a timestamp"], ["C", "Install pandas"], ["D", "Save a CSV"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 39, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df[&quot;purchase_month&quot;] = df[&quot;date&quot;].dt.month\n</code></pre>\n<p>create?</p>", "options": [["A", "Missing values"], ["B", "A derived feature"], ["C", "A duplicate"], ["D", "A database table"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 40, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df[&quot;is_weekend&quot;] = df[&quot;date&quot;].dt.dayofweek &gt; 4\n</code></pre>\n<p>produce?</p>", "options": [["A", "A Boolean weekend feature"], ["B", "A price category"], ["C", "A text token"], ["D", "A standardized score"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 41, "question": "<p>Which method is generally better for <strong>nominal</strong> categories such as colour?</p>", "options": [["A", "Arbitrary integer codes"], ["B", "One-hot encoding"], ["C", "Log transformation"], ["D", "Mean imputation"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 42, "question": "<p>Why may this be dangerous?</p>\n<pre><code class=\"language-text\">Malaysia = 1\nJapan = 2\nBrazil = 3\n</code></pre>", "options": [["A", "Computers cannot process integers"], ["B", "The model may interpret the numbers as meaningful order/magnitude"], ["C", "It always produces missing values"], ["D", "It creates a datetime"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 43, "question": "<p>Which representation avoids implied order?</p>", "options": [["A", "<pre><code class=\"language-text\">Red = 1\nBlue = 2\nGreen = 3\n</code></pre>"], ["B", "<pre><code class=\"language-text\">Red   = [1,0,0]\nBlue  = [0,1,0]\nGreen = [0,0,1]\n</code></pre>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 44, "question": "<p>Which pandas function can perform one-hot encoding?</p>", "options": [["A", "<code>pd.get_dummies()</code>"], ["B", "<code>pd.to_datetime()</code>"], ["C", "<code>df.dropna()</code>"], ["D", "<code>df.info()</code>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 45, "question": "<p>Why is feature scaling especially important for distance-based algorithms?</p>", "options": [["A", "Large-scale variables can dominate distance calculations"], ["B", "It creates labels automatically"], ["C", "It removes all outliers"], ["D", "It converts text into images"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 46, "question": "<p>Which transformation usually maps values into approximately:</p>\n<div class=\"math-display\">$$[0,1]$$</div>", "options": [["A", "Standardization"], ["B", "Min-Max scaling"], ["C", "One-hot encoding"], ["D", "TF-IDF"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 47, "question": "<p>Standardization generally transforms a feature toward:</p>\n<div class=\"math-display\">$$\\text{Mean}=0$$</div>\n<p>and:</p>\n<div class=\"math-display\">$$\\text{StandardDeviation}=1$$</div>\n<p>True or False?</p>", "options": [["A", "True"], ["B", "False"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture contrasts Min-Max scaling with Z-score standardization this way.</p>"}, {"module": 2, "number": 48, "question": "<p>Suppose:</p>\n<div class=\"math-display\">$$\\text{min}=20$$</div>\n<div class=\"math-display\">$$\\text{max}=40$$</div>\n<p>and:</p>\n<div class=\"math-display\">$$x=30$$</div>\n<p>Using Min-Max:</p>\n<div class=\"math-display\">$$x'=\n\\frac{x-\\text{min}}{\\text{max}-\\text{min}}$$</div>\n<div class=\"math-display\">$$=\n\\frac{30-20}{40-20}\n=\n\\frac{10}{20}\n=\n0.5$$</div>\n<p>So:</p>\n<p>Min-Max scaled value of 30 is:</p>", "options": [["A", "0"], ["B", "0.25"], ["C", "0.5"], ["D", "1"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 49, "question": "<p>Lecture 2 only introduces the basics; don't turn this into Lecture 3–4 unnecessarily.</p>\n<p>Know:</p>\n<pre><code class=\"language-text\">Tokenization\nStopword removal\nStemming/Lemmatization\n</code></pre>\n<p>The lecture's example changes:</p>\n<pre><code class=\"language-text\">&quot;The cats are running!&quot;\n</code></pre>\n<p>into roughly:</p>\n<pre><code class=\"language-text\">[&quot;cat&quot;, &quot;run&quot;]\n</code></pre>\n<p>Tokenization means:</p>", "options": [["A", "Scale numbers"], ["B", "Split text into units such as words"], ["C", "Remove duplicates"], ["D", "Create SQL tables"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 50, "question": "<p>Stopwords are:</p>", "options": [["A", "Always-important keywords"], ["B", "Common terms that often carry little useful information"], ["C", "Missing values"], ["D", "Numeric outliers"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 51, "question": "<p>Which best describes stemming/lemmatization?</p>", "options": [["A", "Turn text into images"], ["B", "Reduce related word forms toward a root/canonical form"], ["C", "Remove rows"], ["D", "Detect duplicates"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 52, "question": "<p>What does this calculate?</p>\n<pre><code class=\"language-python\">df.groupby(&quot;user_type&quot;)[&quot;price&quot;].mean()\n</code></pre>", "options": [["A", "Overall price maximum"], ["B", "Mean price for each user type"], ["C", "Number of missing prices"], ["D", "Removes user types"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 53, "question": "<p>What is the conceptual process of <code>groupby()</code>?</p>", "options": [["A", "Train-Test-Evaluate"], ["B", "Split-Apply-Combine"], ["C", "Encode-Scale-Deploy"], ["D", "Crawl-Scrape-Store"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 54, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df.groupby(&quot;user_type&quot;)[&quot;quantity&quot;].sum()\n</code></pre>\n<p>calculate?</p>", "options": [["A", "Total quantity for each user type"], ["B", "Mean user type"], ["C", "Number of columns"], ["D", "Maximum date"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 55, "question": "<p>You want to show monthly revenue from January to December.</p>", "options": [["A", "Histogram"], ["B", "Line chart"], ["C", "Box plot"], ["D", "Pie chart"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 56, "question": "<p>You want to compare sales across:</p>\n<pre><code class=\"language-text\">KL\nPenang\nIpoh\nJohor\n</code></pre>", "options": [["A", "Bar chart"], ["B", "Histogram"], ["C", "Scatter"], ["D", "Line only"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 57, "question": "<p>You want to see the distribution of employee salaries.</p>", "options": [["A", "Histogram"], ["B", "Line"], ["C", "Scatter"], ["D", "Pie"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 58, "question": "<p>You want to identify potential outliers in salary.</p>", "options": [["A", "Line"], ["B", "Box plot"], ["C", "Pie"], ["D", "Map"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 59, "question": "<p>You want to investigate:</p>\n<div class=\"math-display\">$$\\text{AdvertisingSpend}$$</div>\n<p>versus:</p>\n<div class=\"math-display\">$$\\text{Sales}$$</div>", "options": [["A", "Scatter plot"], ["B", "Histogram"], ["C", "Pie chart"], ["D", "Bar chart only"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 60, "question": "<p>A scientist computes Min-Max scaling parameters using both training and test data before training.</p>\n<p>What is the main problem?</p>", "options": [["A", "Overfitting only"], ["B", "Data leakage"], ["C", "Underfitting"], ["D", "Clustering"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 61, "question": "<p>What is the correct approach?</p>", "options": [["A", "<pre><code class=\"language-python\">scaler.fit(X_train)\nX_train = scaler.transform(X_train)\nX_test = scaler.transform(X_test)\n</code></pre>"], ["B", "<pre><code class=\"language-python\">scaler.fit(X_train)\nscaler.fit(X_test)\n</code></pre>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 62, "question": "<p>Why shouldn't you refit preprocessing independently on test/new data?</p>", "options": [["A", "The model expects transformations consistent with training"], ["B", "Pandas prohibits it"], ["C", "Test data cannot contain numbers"], ["D", "It automatically causes duplicates"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture's “Crucial Rule” is that deployment data must go through the <strong>same preprocessing</strong> learned during training.</p>"}, {"module": 2, "number": 63, "question": "<p>A dataset has:</p>\n<pre><code class=\"language-text\">Age        25\nIncome     85000\nCountry    Malaysia\nSignup     2026-01-05\n</code></pre>\n<p>Which combination is most reasonable?</p>", "options": [["A", "TF-IDF Age, histogram Country"], ["B", "Scale Age/Income where needed, encode Country, derive features from Signup"], ["C", "Convert everything to strings"], ["D", "Remove all non-numeric columns"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 64, "question": "<p>A model uses KNN with:</p>\n<pre><code class=\"language-text\">Age: 20–70\nIncome: 20,000–500,000\n</code></pre>\n<p>What should you be most concerned about?</p>", "options": [["A", "Income may dominate the distance calculation"], ["B", "Age becomes text"], ["C", "KNN requires XML"], ["D", "One-hot encoding income"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 65, "question": "<p>A categorical feature contains:</p>\n<pre><code class=\"language-text\">Red\nBlue\nGreen\n</code></pre>\n<p>Someone maps:</p>\n<pre><code class=\"language-text\">Red=1\nBlue=2\nGreen=3\n</code></pre>\n<p>What is the primary concern?</p>", "options": [["A", "Data becomes too small"], ["B", "False ordinal/magnitude relationship"], ["C", "Cannot calculate accuracy"], ["D", "Causes missing values"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 66, "question": "<p>A time-series sensor reading is:</p>\n<pre><code class=\"language-text\">10:00  72\n10:01  NaN\n10:02  73\n</code></pre>\n<p>If the sensor value changes slowly and nearby state reasonably persists, which option may be sensible?</p>", "options": [["A", "One-hot encoding"], ["B", "Forward fill"], ["C", "TF-IDF"], ["D", "SQL join"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 67, "question": "<p>You want to investigate whether transaction amount increases as customer age increases.</p>\n<p>Which visualization?</p>", "options": [["A", "Scatter"], ["B", "Histogram"], ["C", "Bar"], ["D", "Pie"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 68, "question": "<p>You want to understand whether salary contains extreme observations before choosing mean imputation.</p>\n<p>Which visualization is especially useful?</p>", "options": [["A", "Box plot"], ["B", "Line chart"], ["C", "Pie chart"], ["D", "Area chart"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 1, "question": "<p>What is the main purpose of feature engineering?</p>", "options": [["A", "Increase the number of rows"], ["B", "Transform raw data into useful representations for ML"], ["C", "Always remove categorical features"], ["D", "Replace model evaluation"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 2, "question": "<p>Which statement is most consistent with the lecture?</p>", "options": [["A", "Complex algorithms always outperform simple algorithms"], ["B", "Feature engineering is performed only once"], ["C", "Good features can be more important than using a more complex algorithm"], ["D", "Raw data should never be transformed"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 3, "number": 3, "question": "<p>Which sequence best reflects the iterative feature-engineering process?</p>", "options": [["A", "Engineer → Train → Evaluate → Refine"], ["B", "Deploy → Delete → Encode → Train"], ["C", "Evaluate → Collect → Stop"], ["D", "Scale → Deploy → Ignore performance"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 4, "question": "<p>Why is domain knowledge important?</p>", "options": [["A", "It automatically removes all missing data"], ["B", "It helps identify transformations that make sense for the actual problem"], ["C", "It makes test data unnecessary"], ["D", "It replaces mathematics entirely"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 5, "question": "<p>A music recommendation system only needs to know whether a user has ever listened to a song.</p>\n<p>Which transformation is most suitable?</p>", "options": [["A", "Log transformation"], ["B", "Binarization"], ["C", "Dummy coding"], ["D", "TF-IDF"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 6, "question": "<p>Given:</p>\n<pre><code class=\"language-text\">listen_count = [0, 14, 0, 37, 2]\n</code></pre>\n<p>using threshold $&gt;0$, what is the binary result?</p>", "options": [["A", "<code>[0, 14, 0, 37, 2]</code>"], ["B", "<code>[0, 1, 0, 1, 1]</code>"], ["C", "<code>[1, 0, 1, 0, 0]</code>"], ["D", "<code>[0, 0, 0, 1, 1]</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 7, "question": "<p>A sensor outputs:</p>\n<div class=\"math-display\">$$87.638294\\%$$</div>\n<p>but precision beyond the nearest whole percentage is meaningless.</p>\n<p>Which transformation is most appropriate?</p>", "options": [["A", "Binarization"], ["B", "Rounding"], ["C", "One-hot encoding"], ["D", "Hashing"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 8, "question": "<p>Why might excessive decimal precision be harmful?</p>", "options": [["A", "It may represent noise rather than meaningful signal"], ["B", "Decimals cannot be processed by ML"], ["C", "All decimals indicate missing data"], ["D", "It forces unsupervised learning"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 9, "question": "<p>Suppose model performance depends not just on Attack and Defense separately, but on having both high simultaneously.</p>\n<p>Which feature could help?</p>", "options": [["A", "<div class=\"math-display\">$$\\text{Attack}+0$$</div>"], ["B", "<div class=\"math-display\">$$\\text{Attack} \\times \\text{Defense}$$</div>"], ["C", "One-hot encode Attack"], ["D", "Drop Defense"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture uses exactly the interaction:</p>\n<div class=\"math-display\">$$49\\times49=2401$$</div>\n<p>to demonstrate this idea.</p>"}, {"module": 3, "number": 10, "question": "<p>Why create interaction features?</p>", "options": [["A", "To capture relationships between variables that may not be visible when treated independently"], ["B", "To reduce every feature to 0/1"], ["C", "To remove categorical variables"], ["D", "To prevent test/train splitting"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 11, "question": "<p>Given:</p>\n<div class=\"math-display\">$$x_1,\\ x_2$$</div>\n<p>a degree-2 expansion may create:</p>\n<div class=\"math-display\">$$x_1,\\ x_2,\\ x_1^2,\\ x_1x_2,\\ x_2^2$$</div>\n<p>What is a major danger of blindly applying polynomial features to many original columns?</p>", "options": [["A", "Data becomes XML"], ["B", "Feature explosion"], ["C", "Categories become ordinal"], ["D", "Missing values disappear"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture explicitly warns about feature explosion when polynomial expansion is applied to many columns.</p>"}, {"module": 3, "number": 12, "question": "<p>Transforming:</p>\n<div class=\"math-display\">$$\\text{Age}=37$$</div>\n<p>into:</p>\n<pre><code class=\"language-text\">30–39\n</code></pre>\n<p>is called:</p>", "options": [["A", "Scaling"], ["B", "Binning"], ["C", "Stemming"], ["D", "Hashing"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 13, "question": "<p>Which best describes fixed-width bins?</p>", "options": [["A", "Each bin contains equal numbers of observations"], ["B", "Each bin covers equal numerical width"], ["C", "Boundaries are learned only by CNNs"], ["D", "Every value becomes 0 or 1"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 14, "question": "<p>Which is fixed-width?</p>", "options": [["A", "<pre><code class=\"language-text\">0–9\n10–19\n20–29\n30–39\n</code></pre>"], ["B", "<pre><code class=\"language-text\">Lowest 25%\nNext 25%\nNext 25%\nTop 25%\n</code></pre>"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture defines fixed-width binning as predefined ranges of equal or deliberately fixed numerical width.</p>"}, {"module": 3, "number": 15, "question": "<p>Suppose a developer-age feature is transformed as:</p>\n<pre><code class=\"language-text\">0–22   Student\n22–35  Junior\n35–50  Senior\n50–100 Veteran\n</code></pre>\n<p>This is best described as:</p>", "options": [["A", "Quantile binning"], ["B", "Custom/domain-based binning"], ["C", "One-hot encoding"], ["D", "Standardization"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 16, "question": "<p>Why can custom bins be preferable to equal-width bins?</p>", "options": [["A", "They can reflect meaningful business or domain boundaries"], ["B", "They always guarantee equal group sizes"], ["C", "They eliminate missing values"], ["D", "They convert data to text automatically"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 17, "question": "<p>What does quartile binning attempt to produce?</p>", "options": [["A", "Four bins of equal numerical width"], ["B", "Four bins containing approximately 25% of the observations each"], ["C", "Four random bins"], ["D", "Four one-hot columns"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 18, "question": "<p>When is quantile binning especially useful?</p>", "options": [["A", "Highly uneven/skewed distributions"], ["B", "Pure image data only"], ["C", "When every value is identical"], ["D", "When categories already have an order"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 19, "question": "<p>Which situation most strongly suggests considering a log transformation?</p>", "options": [["A", "Country = Malaysia/Japan/UK"], ["B", "Income distribution with a long right tail and a few extremely large values"], ["C", "Colour categories"], ["D", "Missing text"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 20, "question": "<p>What is the major effect of the log transformation?</p>", "options": [["A", "Expands large values even more"], ["B", "Compresses large values and reduces right skew"], ["C", "Converts categories to binary"], ["D", "Sorts records alphabetically"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 21, "question": "<p>What is Box-Cox primarily intended to do?</p>", "options": [["A", "Encode nominal features"], ["B", "Find a useful power transformation that stabilizes variance and makes the distribution more normal-like"], ["C", "Detect duplicates"], ["D", "Generate images"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 22, "question": "<p>What important restriction does the lecture give for Box-Cox?</p>", "options": [["A", "<div class=\"math-display\">$$x&lt;0$$</div>"], ["B", "<div class=\"math-display\">$$x&gt;0$$</div>"], ["C", "Only integer data"], ["D", "Only categorical data"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture notes that Box-Cox searches for a parameter $\\lambda$ and requires strictly positive values.</p>"}, {"module": 3, "number": 23, "question": "<p>Which is nominal?</p>", "options": [["A", "Small, Medium, Large"], ["B", "Primary, Secondary, University"], ["C", "Red, Blue, Green"], ["D", "Low, Medium, High"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 3, "number": 24, "question": "<p>Which is ordinal?</p>", "options": [["A", "Malaysia, Japan, Brazil"], ["B", "Cat, Dog, Horse"], ["C", "Small, Medium, Large"], ["D", "Red, Blue, Green"]], "answers": ["C"], "multiple": false, "explanation": "<p>Nominal categories have no meaningful ordering, while ordinal categories do.</p>"}, {"module": 3, "number": 25, "question": "<p>Suppose:</p>\n<pre><code class=\"language-text\">Action    = 0\nAdventure = 1\nSports    = 2\n</code></pre>\n<p>What is the main danger if these are nominal categories?</p>", "options": [["A", "<p>Model may interpret:</p>\n<div class=\"math-display\">$$\\text{Sports} &gt; \\text{Adventure} &gt; \\text{Action}$$</div>"], ["B", "Model cannot process integers"], ["C", "Values become missing"], ["D", "Dataset becomes too small"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture explicitly warns that numeric labels introduce false magnitude/order when used with nominal categories.</p>"}, {"module": 3, "number": 26, "question": "<p>One-hot encoding of:</p>\n<pre><code class=\"language-text\">Red\nBlue\nGreen\n</code></pre>\n<p>could represent Red as:</p>", "options": [["A", "<code>0</code>"], ["B", "<code>3</code>"], ["C", "<code>[1,0,0]</code>"], ["D", "<code>[1,1,1]</code>"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 3, "number": 27, "question": "<p>With $m$ categories, standard one-hot encoding creates:</p>", "options": [["A", "1 feature"], ["B", "$m-1$ features"], ["C", "$m$ binary features"], ["D", "$2m$ features"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 3, "number": 28, "question": "<p>If a variable has 5 categories, dummy coding normally creates:</p>", "options": [["A", "5 columns"], ["B", "4 columns"], ["C", "1 column"], ["D", "10 columns"]], "answers": ["B"], "multiple": false, "explanation": "<div class=\"math-display\">$$m-1=5-1=4$$</div>"}, {"module": 3, "number": 29, "question": "<p>Why is one category dropped in dummy coding?</p>", "options": [["A", "To provide a reference category and avoid redundant representation in some models"], ["B", "Because the category is invalid"], ["C", "Because pandas cannot store it"], ["D", "To remove missing values"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 30, "question": "<p>How does effect coding differ from dummy coding according to the lecture?</p>", "options": [["A", "The reference category is represented using −1 rather than all zeros"], ["B", "It produces images"], ["C", "It creates $m$ columns"], ["D", "It uses TF-IDF"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 31, "question": "<p>A categorical feature has 100,000 unique product IDs.</p>\n<p>Which technique may reduce dimensionality to a fixed number of columns?</p>", "options": [["A", "One-hot only"], ["B", "Feature hashing"], ["C", "Log transform"], ["D", "Quantile binning"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 32, "question": "<p>What is the major trade-off of feature hashing?</p>", "options": [["A", "Hash collisions"], ["B", "Mandatory missing values"], ["C", "It cannot handle categories"], ["D", "Every category gets its own column"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 1, "question": "<p>What does tokenization do?</p>", "options": [["A", "Scales numbers"], ["B", "Splits text into units such as words"], ["C", "Detects image edges"], ["D", "Calculates cosine similarity"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 2, "question": "<p>Why lowercase text?</p>", "options": [["A", "So <code>\"Machine\"</code> and <code>\"machine\"</code> can be treated consistently"], ["B", "To remove every noun"], ["C", "To scale numbers"], ["D", "To create timestamps"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 3, "question": "<p>Which is a stopword-like term?</p>", "options": [["A", "compressor_failure"], ["B", "bearing"], ["C", "the"], ["D", "turbine"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 4, "number": 4, "question": "<p>Stemming and lemmatization both broadly attempt to:</p>", "options": [["A", "Transform related word forms toward a common form"], ["B", "Turn words into timestamps"], ["C", "Detect outliers"], ["D", "Create image pixels"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 5, "question": "<p>Bag of Words primarily represents text using:</p>", "options": [["A", "RGB values"], ["B", "Word occurrence counts"], ["C", "Time differences"], ["D", "Category hashing only"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 6, "question": "<p>Which vector matches?</p>", "options": [["A", "<code>[1,1,0,0]</code>"], ["B", "<code>[0,0,1,1]</code>"], ["C", "<code>[0,1,0,1]</code>"], ["D", "<code>[1,0,1,0]</code>"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture defines BoW as a term-frequency vector over the corpus vocabulary.</p>"}, {"module": 4, "number": 7, "question": "<p>What is a major limitation of Bag of Words?</p>", "options": [["A", "It cannot represent numbers"], ["B", "It ignores word positions, syntax and semantic meaning"], ["C", "It requires image data"], ["D", "It cannot count repeated words"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 8, "question": "<p>Given:</p>\n<pre><code class=\"language-text\">machine learning model\n</code></pre>\n<p>Which are the bigrams?</p>", "options": [["A", "<code>machine</code>, <code>learning</code>, <code>model</code>"], ["B", "<code>machine learning</code>, <code>learning model</code>"], ["C", "<code>machine learning model</code> only"], ["D", "<code>machine model</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 9, "question": "<p>Why can bigrams help with:</p>\n<pre><code class=\"language-text\">not good\n</code></pre>", "options": [["A", "They can preserve the phrase as a joint feature"], ["B", "They remove the word <code>not</code>"], ["C", "They convert text into images"], ["D", "They make every word identical"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 10, "question": "<p>The intuition:</p>\n<div class=\"math-display\">$$\\text{TF} =\n\\text{importance/frequency within this document}$$</div>\n<div class=\"math-display\">$$\\text{IDF} =\n\\text{rarity across all documents}$$</div>\n<p>The lecture's core idea is:</p>\n<blockquote>\n<p>common-everywhere terms get penalized; distinctive terms get greater weight.</p>\n</blockquote>\n<p>A word appears in every document.</p>\n<p>Its IDF should generally be:</p>", "options": [["A", "High"], ["B", "Low"], ["C", "Infinite"], ["D", "Random"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 11, "question": "<p>A rare term appears in only a few documents.</p>\n<p>Its IDF tends to be:</p>", "options": [["A", "Higher"], ["B", "Zero"], ["C", "Always negative"], ["D", "Equal to term frequency"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 12, "question": "<p>The lecture gives:</p>\n<div class=\"math-display\">$$\\text{TFIDF}=\\text{TF}\\times \\text{IDF}$$</div>\n<p>True or False?</p>", "options": [["A", "True"], ["B", "False"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 13, "question": "<p>The lecture gives:</p>\n<div class=\"math-display\">$$\\cos(\\theta)\n=\n\\frac{A\\cdot B}\n{\\|A\\|\\|B\\|}$$</div>\n<p>If cosine similarity is close to:</p>\n<div class=\"math-display\">$$1$$</div>\n<p>the documents are:</p>", "options": [["A", "Usually very similar in vector direction"], ["B", "Completely unrelated"], ["C", "Duplicates by definition"], ["D", "Missing data"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 14, "question": "<p>If cosine similarity is near:</p>\n<div class=\"math-display\">$$0$$</div>\n<p>the documents are:</p>", "options": [["A", "Highly aligned"], ["B", "Relatively dissimilar"], ["C", "Always identical"], ["D", "Ordinal"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 15, "question": "<p>A set of unlabeled documents is converted to TF-IDF vectors and automatically grouped into similar topics.</p>\n<p>This is:</p>", "options": [["A", "Regression"], ["B", "Unsupervised clustering"], ["C", "Supervised classification"], ["D", "Reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture demonstrates weather documents clustering separately from animal documents.</p>"}, {"module": 4, "number": 16, "question": "<p>What does LDA attempt to discover?</p>", "options": [["A", "Missing values"], ["B", "Latent topics/themes in documents"], ["C", "RGB channels"], ["D", "Numeric outliers"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 17, "question": "<p>In topic modelling, a document may contain:</p>", "options": [["A", "Exactly one word"], ["B", "A mixture of multiple topics"], ["C", "Only one mandatory topic"], ["D", "No numeric representation"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 18, "question": "<p>Which best describes word embeddings?</p>", "options": [["A", "Sparse one-hot vectors only"], ["B", "Dense numerical vectors where semantically related words can be nearby"], ["C", "Timestamps for words"], ["D", "Image pixels"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 19, "question": "<p>Why might vectors for <code>\"king\"</code> and <code>\"queen\"</code> be closer than <code>\"king\"</code> and <code>\"car\"</code>?</p>", "options": [["A", "They occur in more similar linguistic contexts"], ["B", "They have the same spelling"], ["C", "They always have the same length"], ["D", "They are one-hot encoded"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 20, "question": "<p>CBOW roughly predicts:</p>", "options": [["A", "Context from target word"], ["B", "Target word from context"], ["C", "RGB from grayscale"], ["D", "Topic from timestamp"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 21, "question": "<p>Skip-gram roughly predicts:</p>", "options": [["A", "Context from target word"], ["B", "Target word from context"], ["C", "Income from age"], ["D", "Categories from quantiles"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture explicitly contrasts CBOW and Skip-gram this way.</p>"}, {"module": 4, "number": 22, "question": "<p>Suppose:</p>\n<pre><code class=\"language-text\">2026-09-23 14:35:22\n</code></pre>\n<p>You can derive:</p>\n<pre><code class=\"language-text\">year\nmonth\nday\nquarter\nday_of_week\nhour\n</code></pre>\n<p>The lecture explicitly lists these kinds of features.</p>\n<p>Extracting <code>month</code> from a timestamp is:</p>", "options": [["A", "Feature engineering"], ["B", "Data deletion"], ["C", "Topic modelling"], ["D", "Image segmentation"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 23, "question": "<p>Why can extracted time components be better than the raw timestamp?</p>", "options": [["A", "They can expose patterns such as weekend, season or time-of-day"], ["B", "Models cannot process any numeric values"], ["C", "They always reduce rows"], ["D", "They remove categories"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 24, "question": "<p>Suppose:</p>\n<pre><code class=\"language-text\">14:35\n</code></pre>\n<p>becomes:</p>\n<pre><code class=\"language-text\">Afternoon\n</code></pre>\n<p>This combines:</p>", "options": [["A", "Time extraction + binning"], ["B", "TF-IDF + hashing"], ["C", "CNN + clustering"], ["D", "Dummy coding + stemming"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 25, "question": "<p>Malaysia:</p>\n<pre><code class=\"language-text\">14:00 UTC+8\n</code></pre>\n<p>London:</p>\n<pre><code class=\"language-text\">06:00 UTC+0\n</code></pre>\n<p>These may represent:</p>", "options": [["A", "Completely different days only"], ["B", "The same moment in time"], ["C", "Missing data"], ["D", "Image coordinates"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 26, "question": "<p>Why normalize timestamps to UTC?</p>", "options": [["A", "To make global timestamps share a consistent temporal reference"], ["B", "To perform one-hot encoding"], ["C", "To eliminate all seasons"], ["D", "To create TF-IDF vectors"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 27, "question": "<p>Unix Epoch time represents:</p>", "options": [["A", "Days since year 1"], ["B", "Seconds since 1 January 1970 UTC"], ["C", "Months since 1900"], ["D", "Hours since model training"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 28, "question": "<p>Why can epoch/ordinal representations be useful?</p>", "options": [["A", "Easier elapsed-time calculations"], ["B", "They automatically classify observations"], ["C", "They remove images"], ["D", "They eliminate the need for timestamps"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 29, "question": "<p>An RGB image generally has shape:</p>\n<div class=\"math-display\">$$(m,n,c)$$</div>\n<p>where $c$ usually equals:</p>", "options": [["A", "1"], ["B", "2"], ["C", "3"], ["D", "255"]], "answers": ["C"], "multiple": false, "explanation": "<p>Red, Green and Blue channels.</p>"}, {"module": 4, "number": 30, "question": "<p>In:</p>\n<div class=\"math-display\">$$(m,n,3)$$</div>\n<p>$m$ and $n$ represent:</p>", "options": [["A", "Model and noise"], ["B", "Image rows/height and columns/width"], ["C", "Month and number"], ["D", "Mean and normalization"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 31, "question": "<p>The lecture gives approximately:</p>\n<div class=\"math-display\">$$Y=\n0.2125R+\n0.7154G+\n0.0721B$$</div>\n<p>Converting RGB to grayscale changes approximately:</p>\n<div class=\"math-display\">$$(m,n,3)$$</div>\n<p>to:</p>", "options": [["A", "<div class=\"math-display\">$$(m,n)$$</div>"], ["B", "<div class=\"math-display\">$$(3,m,n,3)$$</div>"], ["C", "<div class=\"math-display\">$$1$$</div>"], ["D", "<div class=\"math-display\">$$(m^2,n^2)$$</div>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 32, "question": "<p>Why might grayscale be useful?</p>", "options": [["A", "Reduces dimensionality while preserving intensity information"], ["B", "Adds more colour channels"], ["C", "Converts images into text"], ["D", "Creates categories automatically"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 33, "question": "<p>A matrix:</p>\n<pre><code class=\"language-text\">0.2 0.5\n0.7 0.9\n</code></pre>\n<p>can become:</p>\n<pre><code class=\"language-text\">[0.2, 0.5, 0.7, 0.9]\n</code></pre>\n<p>This is called:</p>", "options": [["A", "Flattening"], ["B", "Tokenization"], ["C", "Binning"], ["D", "Lemmatization"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 34, "question": "<p>What is the main drawback?</p>", "options": [["A", "Spatial neighbour relationships are largely lost"], ["B", "Pixel values disappear"], ["C", "Image size doubles"], ["D", "It creates extra colour channels"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 35, "question": "<p>An image histogram can represent:</p>", "options": [["A", "Number of pixels falling into different intensity ranges"], ["B", "Word frequencies"], ["C", "Time zones"], ["D", "Categorical rankings"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 36, "question": "<p>A mostly bright image is likely to have more pixel counts:</p>", "options": [["A", "At higher intensity values"], ["B", "Only at zero"], ["C", "At negative intensity"], ["D", "At random text labels"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 37, "question": "<p>Which can summarize image intensity distributions?</p>", "options": [["A", "Mean, variance, skewness, kurtosis"], ["B", "Only SQL queries"], ["C", "TF-IDF only"], ["D", "Generation labels"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 38, "question": "<p>What does edge detection primarily seek?</p>", "options": [["A", "Sharp changes in intensity/brightness"], ["B", "Missing image labels"], ["C", "Word counts"], ["D", "Time zones"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 39, "question": "<p>Which algorithm is specifically mentioned in the lecture?</p>", "options": [["A", "Canny"], ["B", "Apriori"], ["C", "PageRank"], ["D", "ARIMA"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 40, "question": "<p>HOG stands for:</p>", "options": [["A", "Histogram of Oriented Gradients"], ["B", "Hierarchy of Global Groups"], ["C", "High Order Gaussian"], ["D", "Hash of Gradients"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 41, "question": "<p>HOG primarily captures:</p>", "options": [["A", "Edge directions/orientations and local shape information"], ["B", "Word semantics"], ["C", "SQL structure"], ["D", "Datetime offsets"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 42, "question": "<p>SURF is mainly associated with:</p>", "options": [["A", "Localized feature extraction around interesting image points"], ["B", "Text stemming"], ["C", "Time binning"], ["D", "Categorical encoding"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 43, "question": "<p>SURF stands for:</p>", "options": [["A", "Standard Unified Regression Features"], ["B", "Speeded Up Robust Features"], ["C", "Structured Universal Ranking Formula"], ["D", "Scaled Unsupervised Random Forest"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 44, "question": "<p>Visual Bag of Words is inspired by:</p>", "options": [["A", "Text Bag of Words"], ["B", "Min-Max scaling"], ["C", "Regression"], ["D", "Epoch timestamps"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 45, "question": "<p>The basic VBOW flow is approximately:</p>\n<div class=\"math-flow\" role=\"img\" aria-label=\"Image → Local descriptors → Clusters → Visual words → Count vector\"><span>Image</span><i aria-hidden=\"true\">→</i><span>Local descriptors</span><i aria-hidden=\"true\">→</i><span>Clusters</span><i aria-hidden=\"true\">→</i><span>Visual words</span><i aria-hidden=\"true\">→</i><span>Count vector</span></div>\n<p>True or False?</p>", "options": [["A", "True"], ["B", "False"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture describes clustering local descriptors and treating clusters as visual words.</p>"}, {"module": 4, "number": 46, "question": "<p>What major change do CNNs bring compared with traditional image-feature engineering?</p>", "options": [["A", "CNNs can learn useful feature representations automatically"], ["B", "CNNs require all features to be manually designed"], ["C", "CNNs convert images to SQL"], ["D", "CNNs eliminate numerical input"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 47, "question": "<p>Early CNN layers commonly learn:</p>", "options": [["A", "Edges and lines"], ["B", "Entire high-level objects immediately"], ["C", "Time zones"], ["D", "Document topics"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 48, "question": "<p>Deeper CNN layers generally learn:</p>", "options": [["A", "Increasingly complex patterns/concepts"], ["B", "Only pixel brightness"], ["C", "Missing-value indicators"], ["D", "Stopwords"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 49, "question": "<p>The lecture closes with the correct order:</p>\n<div class=\"math-flow\" role=\"img\" aria-label=\"Train/Test Split → Fit Transformers on Train → Transform Train → Transform Test → Train Model → Evaluate\"><span>Train/Test Split</span><i aria-hidden=\"true\">→</i><span>Fit Transformers on Train</span><i aria-hidden=\"true\">→</i><span>Transform Train</span><i aria-hidden=\"true\">→</i><span>Transform Test</span><i aria-hidden=\"true\">→</i><span>Train Model</span><i aria-hidden=\"true\">→</i><span>Evaluate</span></div>\n<p>Why split train/test <strong>before</strong> fitting TF-IDF, quantile binning, scalers or encoders?</p>", "options": [["A", "To avoid test information leaking into preprocessing"], ["B", "To increase image resolution"], ["C", "To convert categories to text"], ["D", "To reduce rows automatically"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 50, "question": "<p>Which is wrong?</p>", "options": [["A", "Fit TF-IDF vocabulary on train, transform train/test"], ["B", "Fit encoder on train, reuse on test"], ["C", "Refit preprocessing separately on test"], ["D", "Split before learning preprocessing parameters"]], "answers": ["C"], "multiple": false, "explanation": ""}];
